//! Writes the Rust code of a catalog: its struct, its table and its lookup.

use std::collections::BTreeSet;

use proc_macro2::{Delimiter, Ident, Spacing, Span, TokenStream, TokenTree};
use quote::{format_ident, quote};

use crate::bki::Catalog;
use crate::column::{oid_value, ColumnKind, Field};
use crate::sql::TableSql;

pub(crate) const HEADER: &str = "\
// @generated by turso_pg_catalog_gen from upstream/postgres.bki.
// Do not edit. To change this file, run postgres/catalog/update.sh or
// `cargo run -p turso_pg_catalog_gen`.

use crate::Oid;
";

/// The catalogs whose built-in rows the generated file leaves out, each
/// with the reason, which the documentation of its table gives.
const ROWS_LEFT_OUT: [(&str, &str); 3] = [
    (
        "pg_class",
        "`postgres.bki` has rows for only the four catalogs that PostgreSQL needs to start. \
         `initdb` makes the other rows",
    ),
    (
        "pg_attribute",
        "`postgres.bki` has rows for only the four catalogs that PostgreSQL needs to start. \
         `initdb` makes the other rows",
    ),
    (
        "pg_database",
        "its row has the encoding and the locale of the cluster, which only `initdb` knows",
    ),
];

/// Writes the struct, the table and the lookup of one catalog.
pub(crate) fn emit_catalog(code: &mut String, catalog: &Catalog) -> Result<(), String> {
    let in_catalog = |message: String| format!("{}: {message}", catalog.name);
    let fields = Field::of_catalog(catalog).map_err(in_catalog)?;

    let name = &catalog.name;
    let struct_name = Ident::new(&struct_name(name), Span::call_site());
    let table_name = Ident::new(&name.to_uppercase(), Span::call_site());
    let field_names: Vec<Ident> = fields.iter().map(Field::ident).collect();

    let field_types = fields.iter().map(Field::rust_type);
    let struct_doc = format!(" A row of `{name}`.");
    code.push('\n');
    code.push_str(&formatted(quote! {
        #[doc = #struct_doc]
        #[derive(Debug, Clone, Copy, PartialEq)]
        pub struct #struct_name {
            #(pub #field_names: #field_types,)*
        }
    }));

    // The oid that identifies a row, for a catalog that has one: the
    // first column, when a unique index is on that column alone.
    let key = fields.first().filter(|first| {
        first.kind == ColumnKind::Oid && !first.nullable && catalog.has_unique_index_on(first.name)
    });

    // The column `oid` is the rowid when a unique index is on it alone, as
    // the oid then identifies a row.
    let rowid_column = match key {
        Some(key) if key.name == "oid" => Some(key.name),
        _ if catalog.has_unique_index_on("oid") => {
            return Err(in_catalog(
                "a unique index is on oid alone, and oid is not the first column".to_string(),
            ))
        }
        _ => None,
    };
    let table_sql = TableSql::of_catalog(catalog, &fields, rowid_column).map_err(in_catalog)?;

    let left_out = ROWS_LEFT_OUT
        .iter()
        .find(|(catalog, _)| catalog == name)
        .map(|(_, reason)| reason);

    let mut rows = Vec::new();
    if left_out.is_none() {
        for (position, row) in catalog.rows.iter().enumerate() {
            let mut values = Vec::new();
            for (field, token) in fields.iter().zip(row) {
                values.push(field.literal(token).map_err(|message| {
                    in_catalog(format!(
                        "row {}, column {}: {message}",
                        position + 1,
                        field.name
                    ))
                })?);
            }
            let key_value = match key {
                Some(_) => oid_value(&row[0]).map_err(in_catalog)?,
                None => 0,
            };
            let literal = quote! { #struct_name { #(#field_names: #values),* } };
            rows.push((key_value, literal));
        }
    }
    if let Some(key) = key {
        // The lookup is a binary search.
        rows.sort_by_key(|(key_value, _)| *key_value);
        let distinct: BTreeSet<u32> = rows.iter().map(|(key_value, _)| *key_value).collect();
        if distinct.len() != rows.len() {
            return Err(in_catalog(format!("two rows have the same {}", key.name)));
        }
    }

    // prettyplease writes each field of a struct expression on its own
    // line, which is 31 lines for each of the 3,397 rows of `pg_proc`.
    // The table is thus written here, one row on a line.
    let table_doc = match (left_out, key) {
        (Some(reason), _) => format!("`{name}` without rows: {reason}."),
        (None, Some(key)) => format!(
            "The built-in rows of `{name}`, in the order of `{}`.",
            key.name
        ),
        (None, None) => format!("The built-in rows of `{name}`, in the order of `postgres.bki`."),
    };
    let row_count = rows.len();
    code.push_str(&format!(
        "\n/// {table_doc}\npub static {table_name}: [{struct_name}; {row_count}] = [\n"
    ));
    for (_, literal) in rows {
        code.push_str("    ");
        write_on_one_line(code, literal);
        code.push_str(",\n");
    }
    code.push_str("];\n");

    let create_doc = format!(
        " The `CREATE TABLE` statement of `{name}` in SQLite syntax, with the \
         columns in the order of `postgres.bki`."
    );
    let index_doc = match rowid_column {
        Some(rowid) => format!(
            " The `CREATE INDEX` statements of `{name}` in SQLite syntax: one for \
             each index of `postgres.bki`, except the unique index on `{rowid}`, \
             which the `INTEGER PRIMARY KEY` replaces."
        ),
        None => format!(
            " The `CREATE INDEX` statements of `{name}` in SQLite syntax: one for \
             each index of `postgres.bki`."
        ),
    };
    let create_sql = &table_sql.create_sql;
    let index_sql = &table_sql.index_sql;
    let lookup = key.map(|key| {
        let key_name = key.ident();
        let lookup = format_ident!("by_{key_name}");
        let lookup_doc = format!(" The built-in row whose `{key_name}` is `{key_name}`.");
        quote! {
            #[doc = #lookup_doc]
            pub fn #lookup(#key_name: Oid) -> Option<&'static #struct_name> {
                let position = #table_name
                    .binary_search_by_key(&#key_name, |row| row.#key_name)
                    .ok()?;
                Some(&#table_name[position])
            }
        }
    });
    code.push('\n');
    code.push_str(&formatted(quote! {
        impl #struct_name {
            #[doc = #create_doc]
            pub const CREATE_SQL: &'static str = #create_sql;
            #[doc = #index_doc]
            pub const INDEX_SQL: &'static [&'static str] = &[#(#index_sql),*];
            #lookup
        }
    }));
    Ok(())
}

/// The source text of `items`, with the layout of prettyplease.
fn formatted(items: TokenStream) -> String {
    let file = syn::parse2(items).expect("the generator writes valid Rust items");
    prettyplease::unparse(&file)
}

/// Appends the source text of `tokens` to `code` without a line break.
/// A space follows a comma and a colon, and is inside braces. This is how
/// rustfmt writes a short struct expression.
fn write_on_one_line(code: &mut String, tokens: TokenStream) {
    for tree in tokens {
        match tree {
            TokenTree::Group(group) => {
                let (open, close) = match group.delimiter() {
                    Delimiter::Parenthesis => ("(", ")"),
                    Delimiter::Bracket => ("[", "]"),
                    Delimiter::Brace => (" { ", " }"),
                    Delimiter::None => ("", ""),
                };
                code.push_str(open);
                write_on_one_line(code, group.stream());
                code.push_str(close);
            }
            TokenTree::Punct(punct) => {
                code.push(punct.as_char());
                // `::` has no space in it or after it.
                if matches!(punct.as_char(), ',' | ':') && punct.spacing() == Spacing::Alone {
                    code.push(' ');
                }
            }
            TokenTree::Ident(ident) => code.push_str(&ident.to_string()),
            TokenTree::Literal(literal) => code.push_str(&literal.to_string()),
        }
    }
}

/// `pg_opfamily` becomes `PgOpfamily`.
fn struct_name(catalog: &str) -> String {
    catalog
        .split('_')
        .map(|word| {
            let mut letters = word.chars();
            match letters.next() {
                Some(first) => first.to_uppercase().chain(letters).collect::<String>(),
                None => String::new(),
            }
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::bki::parse;

    const SMALL: &str = "\
# PostgreSQL 18
create pg_namespace 2615
 (
 oid = oid ,
 nspname = name ,
 nspacl = _aclitem
 )
open pg_namespace
insert ( 99 pg_toast _null_ )
insert ( 11 pg_catalog '{a=b,c=d}' )
close pg_namespace
declare unique index pg_namespace_oid_index 2685 on pg_namespace using btree(oid oid_ops)
";

    #[test]
    fn rows_are_sorted_by_the_first_column_and_a_null_makes_the_column_optional() {
        let catalogs = parse(SMALL).unwrap();
        let mut code = String::new();
        emit_catalog(&mut code, &catalogs[0]).unwrap();
        assert!(code.contains("pub nspacl: Option<&'static [&'static str]>,"));
        let pg_catalog = code.find("oid: 11, nspname: \"pg_catalog\"").unwrap();
        let pg_toast = code
            .find("oid: 99, nspname: \"pg_toast\", nspacl: None")
            .unwrap();
        assert!(pg_catalog < pg_toast);
        assert!(code.contains("nspacl: Some(&[\"a=b\", \"c=d\"])"));
    }

    #[test]
    fn an_unknown_column_type_stops_the_generation() {
        let bki = "create pg_am 2601\n (\n oid = oid ,\n amlsn = mystery\n )\nopen pg_am\ninsert ( 2 0 )\nclose pg_am\n";
        let catalogs = parse(bki).unwrap();
        let error = emit_catalog(&mut String::new(), &catalogs[0]).unwrap_err();
        assert_eq!(
            error,
            "pg_am: column amlsn has type mystery, which the generator does not know"
        );
    }

    #[test]
    fn a_row_is_written_on_one_line_as_rustfmt_writes_a_short_struct() {
        let mut code = String::new();
        write_on_one_line(
            &mut code,
            quote! { PgProc { oid: 1, typlen: -1, name: "a, b", args: Some(&[1, 2]), acl: None } },
        );
        assert_eq!(
            code,
            "PgProc { oid: 1, typlen: -1, name: \"a, b\", args: Some(&[1, 2]), acl: None }"
        );
    }

    #[test]
    fn a_catalog_without_a_unique_index_on_its_first_column_has_no_lookup() {
        let bki = "create pg_depend 2608\n (\n classid = oid ,\n objid = oid\n )\n\
                   open pg_depend\ninsert ( 9 1 )\ninsert ( 3 2 )\nclose pg_depend\n\
                   declare unique index pg_depend_both_index 2673 on pg_depend using btree(classid oid_ops, objid oid_ops)\n";
        let catalogs = parse(bki).unwrap();
        let mut code = String::new();
        emit_catalog(&mut code, &catalogs[0]).unwrap();
        assert!(!code.contains("pub fn by_"), "{code}");
        // The rows stay in the order of the file.
        let first = code.find("PgDepend { classid: 9, objid: 1 }").unwrap();
        let second = code.find("PgDepend { classid: 3, objid: 2 }").unwrap();
        assert!(first < second);
    }

    #[test]
    fn a_unique_index_on_an_oid_that_is_not_the_first_column_stops_the_generation() {
        let bki = "create pg_am 2601\n (\n amname = name ,\n oid = oid\n )\n\
                   declare unique index pg_am_oid_index 2652 on pg_am using btree(oid oid_ops)\n";
        let catalogs = parse(bki).unwrap();
        let error = emit_catalog(&mut String::new(), &catalogs[0]).unwrap_err();
        assert_eq!(
            error,
            "pg_am: a unique index is on oid alone, and oid is not the first column"
        );
    }

    #[test]
    fn a_catalog_has_its_create_table_and_create_index_statements() {
        let catalogs = parse(SMALL).unwrap();
        let mut code = String::new();
        emit_catalog(&mut code, &catalogs[0]).unwrap();
        assert!(code.contains(
            "pub const CREATE_SQL: &'static str = \"CREATE TABLE pg_namespace(oid INTEGER PRIMARY KEY, \
             nspname TEXT NOT NULL, nspacl TEXT)\";"
        ));
        assert!(code.contains("pub const INDEX_SQL: &'static [&'static str] = &[];"));
    }

    #[test]
    fn a_null_in_a_column_that_is_not_null_stops_the_generation() {
        let bki = "create pg_am 2601\n (\n oid = oid ,\n amtype = char\n )\n\
                   open pg_am\ninsert ( 2 _null_ )\nclose pg_am\n";
        let catalogs = parse(bki).unwrap();
        let error = emit_catalog(&mut String::new(), &catalogs[0]).unwrap_err();
        assert_eq!(
            error,
            "pg_am: row 1, column amtype: the column is NOT NULL and the row has NULL in it"
        );
    }
}
